import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../context/AuthContext';

const ChatPanel = ({ socket }) => {
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [onlineUsers, setOnlineUsers] = useState(0);
  const [isTyping, setIsTyping] = useState({});
  const { user } = useAuth();
  const messagesEndRef = useRef(null);
  const inputRef = useRef(null);

  useEffect(() => {
    if (socket) {
      // Join chat room
      socket.emit('joinChat', { userId: user?.id, username: user?.displayName || 'Anonymous' });

      // Listen for new messages
      socket.on('receiveMessage', (message) => {
        setMessages(prev => [...prev, message]);
      });

      // Listen for online user count
      socket.on('onlineCountUpdate', (data) => {
        setOnlineUsers(data.count);
      });

      // Listen for typing indicators
      socket.on('typingStart', (data) => {
        setIsTyping(prev => ({ ...prev, [data.userId]: true }));
      });

      socket.on('typingStop', (data) => {
        setIsTyping(prev => {
          const newTyping = { ...prev };
          delete newTyping[data.userId];
          return newTyping;
        });
      });

      // Initial fetch of recent messages
      fetchRecentMessages();
    }

    return () => {
      if (socket) {
        socket.off('receiveMessage');
        socket.off('onlineCountUpdate');
        socket.off('typingStart');
        socket.off('typingStop');
      }
    };
  }, [socket, user]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const fetchRecentMessages = async () => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/chat/messages`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (response.ok) {
        const data = await response.json();
        setMessages(data.messages || []);
      }
    } catch (error) {
      console.error('Error fetching chat messages:', error);
    }
  };

  const handleSendMessage = async (e) => {
    e.preventDefault();
    if (!inputMessage.trim() || !user) return;

    const messageData = {
      userId: user.id,
      username: user.displayName,
      message: inputMessage,
      timestamp: new Date().toISOString()
    };

    // Optimistically add message to UI
    setMessages(prev => [...prev, messageData]);
    setInputMessage('');

    try {
      // Send to server via socket
      socket.emit('sendMessage', messageData);

      // Also send to backend for persistence
      await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/chat/send`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify(messageData)
      });
    } catch (error) {
      console.error('Error sending message:', error);
    }
  };

  const handleInputChange = (e) => {
    const value = e.target.value;
    setInputMessage(value);

    // Emit typing indicator
    if (value.length > 0) {
      socket.emit('typingStart', { userId: user?.id, username: user?.displayName });
      clearTimeout(window.typingTimeout);
      window.typingTimeout = setTimeout(() => {
        socket.emit('typingStop', { userId: user?.id });
      }, 1000);
    } else {
      socket.emit('typingStop', { userId: user?.id });
    }
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const formatTime = (timestamp) => {
    return new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const getTypingUsers = () => {
    return Object.entries(isTyping)
      .filter(([userId, isTyping]) => isTyping)
      .map(([userId, isTyping], index, arr) => {
        // Find the username from messages
        const userMsg = messages.find(msg => msg.userId === parseInt(userId));
        const username = userMsg ? userMsg.username : `User${userId}`;
        return (
          <span key={userId}>
            {username}{index < arr.length - 1 ? ', ' : ''}
          </span>
        );
      });
  };

  return (
    <div className="chat-panel">
      <div className="chat-header">
        <h3>Live Chat</h3>
        <div className="chat-stats">
          <span className="online-count">👥 {onlineUsers} online</span>
        </div>
      </div>

      <div className="chat-messages">
        {messages.map((msg, index) => (
          <div key={index} className={`chat-message ${msg.userId === user?.id ? 'own-message' : ''}`}>
            <div className="message-header">
              <span className="username">{msg.username}</span>
              <span className="timestamp">{formatTime(msg.timestamp)}</span>
            </div>
            <div className="message-content">{msg.message}</div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {Object.keys(isTyping).length > 0 && (
        <div className="typing-indicator">
          {getTypingUsers()} {Object.keys(isTyping).length === 1 ? 'is' : 'are'} typing...
        </div>
      )}

      <form className="chat-input-form" onSubmit={handleSendMessage}>
        <input
          ref={inputRef}
          type="text"
          value={inputMessage}
          onChange={handleInputChange}
          placeholder="Type a message..."
          className="chat-input"
          maxLength={500}
        />
        <button type="submit" className="send-button" disabled={!inputMessage.trim()}>
          📤
        </button>
      </form>
    </div>
  );
};

export default ChatPanel;
